import json, sys

def get_text(content):
    out = []
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        for block in content:
            if not isinstance(block, dict):
                continue
            t = block.get('type')
            if t == 'text':
                out.append(block.get('text',''))
            elif t == 'tool_use':
                inp = block.get('input', {})
                # truncate long inputs
                s = json.dumps(inp)[:300]
                out.append(f"[tool_use:{block.get('name')}] {s}")
            elif t == 'tool_result':
                c = block.get('content')
                if isinstance(c, list):
                    for cc in c:
                        if isinstance(cc, dict) and cc.get('type')=='text':
                            txt = cc.get('text','')
                            out.append(f"[tool_result] {txt[:300]}")
                elif isinstance(c, str):
                    out.append(f"[tool_result] {c[:300]}")
    return "\n".join(out)

fname = sys.argv[1]
with open(fname) as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            d = json.loads(line)
        except Exception:
            continue
        typ = d.get('type')
        ts = d.get('timestamp','')
        if typ == 'operation':
            continue
        msg = d.get('message')
        role = None
        text = ''
        if msg:
            role = msg.get('role')
            text = get_text(msg.get('content'))
        elif 'content' in d and isinstance(d.get('content'), str):
            role = typ
            text = d.get('content')
        if text:
            text = text.strip()
            if len(text) > 1500:
                text = text[:1500] + " ...[TRUNCATED]"
            print(f"--- {ts} {typ}/{role} ---")
            print(text)
EOF
